    # Verify all LEAP totals
    for idea in new_directory_ideas:
        calculated = idea['leap_l'] + idea['leap_e'] + idea['leap_a'] + idea['leap_p']
        if calculated != idea['leap_total']:
            print(f"LEAP mismatch for {idea['id']}: calculated {calculated}, stored {idea['leap_total']}")

    print("\nAll LEAP totals verified!")
